const updatesRes = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://api.telegram.org/bot${CFG.TG_TOKEN}/getUpdates?offset=${(state.last_update_id || 0) + 1}&timeout=1`,
  json: true
});

for (const u of (updatesRes.result || [])) {
  state.last_update_id = Math.max(state.last_update_id || 0, u.update_id);
  if (u.message && u.message.text) {
    await handleCommand(this, String(u.message.chat.id), u.message.text.trim());
  } else if (u.callback_query) {
    const cb = u.callback_query;
    const chatId = String(cb.message.chat.id);
    const data = cb.data || '';
    await tgSend(this, 'answerCallbackQuery', { callback_query_id: cb.id });

    if (data.startsWith('simpler:')) {
      await sendCurrentStep(this, chatId, true);
    } else if (data.startsWith('qans:')) {
      // Format: qans:L1_1:A -> We know 100% which Lesson ID and which Option ID was clicked!
      const parts = data.split(':');
      const lesId = parts[1];
      const chosen = parts[2];
      const lesIdx = CURRICULUM.findIndex(x => x.id === lesId);
      if (lesIdx >= 0) {
        const les = CURRICULUM[lesIdx];
        if (chosen === les.correct) {
          state.lessons_done[les.id] = 'mastered';
          if (state.current_idx === lesIdx && state.current_idx < CURRICULUM.length - 1) {
            state.current_idx = lesIdx + 1;
          }
          const nextLes = CURRICULUM[state.current_idx];
          await tgSend(this, 'sendMessage', {
            chat_id: chatId,
            parse_mode: 'Markdown',
            text: `${les.whyRight}\n\n✅ *Recorded in Scorecard*: \`${les.id} = MASTERED\``,
            reply_markup: {
              inline_keyboard: [
                [{ text: `➡️ Go to Next Lesson (${nextLes.id})`, callback_data: '/quiz' }],
                [{ text: '🎓 See Today\'s Trade At My Level', callback_data: '/classroom' }]
              ]
            }
          });
        } else {
          state.wrong_queue.push(les.id);
          await tgSend(this, 'sendMessage', {
            chat_id: chatId,
            parse_mode: 'Markdown',
            text: `${les.whyWrong}\n\n👇 *Try this same question one more time (or tap Explain Simpler):*`,
            reply_markup: {
              inline_keyboard: [
                [{ text: les.options[0].text, callback_data: `qans:${les.id}:A` }],
                [{ text: les.options[1].text, callback_data: `qans:${les.id}:B` }],
                [{ text: '👶 Explain Even Simpler', callback_data: `simpler:${les.id}` }]
              ]
            }
          });
        }
      }
    } else {
      await handleCommand(this, chatId, data);
    }
  }
}

